"""Keyed totals: sum values by key and answer queries (see BRIEF.md)."""

import re
import sys

INT64_MIN = -(2**63)
INT64_MAX = 2**63 - 1
VALUE_RE = re.compile(rb"-?[0-9]+")
OVERFLOW = object()


def _lines(data: bytes):
    if data.startswith(b"\xef\xbb\xbf"):
        data = data[3:]
    lines = data.split(b"\n")
    if lines and lines[-1] == b"":
        lines.pop()  # trailing newline terminates the last line
    return [line[:-1] if line.endswith(b"\r") else line for line in lines]


def solve(data: bytes) -> bytes:
    """Return the full stdout for the given input file contents."""
    lines = _lines(data)
    try:
        sep = lines.index(b"")
    except ValueError:
        sep = len(lines)
    records, queries = lines[:sep], lines[sep + 1:]

    totals = {}
    for line in records:
        key, _, value = line.partition(b" ")
        if not VALUE_RE.fullmatch(value):
            continue  # malformed record
        current = totals.get(key, 0)
        if current is OVERFLOW:
            continue
        current += int(value)
        totals[key] = current if INT64_MIN <= current <= INT64_MAX else OVERFLOW

    out = []
    for key in queries:
        if key == b"":
            continue
        total = totals.get(key)
        if total is None:
            result = b"absent"
        elif total is OVERFLOW:
            result = b"overflow"
        else:
            result = str(total).encode()
        out.append(key + b"=" + result + b"\n")
    return b"".join(out)


def main(argv=None) -> int:
    argv = sys.argv if argv is None else argv
    with open(argv[1], "rb") as f:
        data = f.read()
    sys.stdout.buffer.write(solve(data))
    sys.stdout.buffer.flush()
    return 0


if __name__ == "__main__":
    sys.exit(main())
