import subprocess
import sys
from pathlib import Path

from main import solve

MAIN = Path(__file__).resolve().parent.parent / "main.py"
MAX = 2**63 - 1
MIN = -(2**63)


def run(text: str) -> str:
    return solve(text.encode("utf-8")).decode("utf-8")


def test_basic():
    assert run("a 1\nb 2\na 3\n\na\nb\nc\n") == "a=4\nb=2\nc=absent\n"


def test_empty_file():
    assert run("") == ""
    assert run("\n") == ""


def test_no_records_with_queries():
    assert run("\nx\n") == "x=absent\n"


def test_records_no_queries():
    assert run("a 1\n\n") == ""
    assert run("a 1\n") == ""


def test_no_trailing_newline():
    assert run("a 1\n\na") == "a=1\n"


def test_crlf():
    assert run("a 1\r\n\r\na\r\n") == "a=1\n"


def test_unicode_keys_compared_by_bytes():
    # NFC "é" vs NFD "é" are different keys
    text = "é 1\né 2\n日本 5\n\né\né\n日本\n"
    assert run(text) == "é=1\né=2\n日本=5\n"


def test_case_sensitive():
    assert run("A 1\n\na\nA\n") == "a=absent\nA=1\n"


def test_extremes():
    assert run(f"a {MAX}\nb {MIN}\n\na\nb\n") == f"a={MAX}\nb={MIN}\n"


def test_overflow_up_and_down():
    assert run(f"a {MAX}\na 1\nb {MIN}\nb -1\n\na\nb\n") == "a=overflow\nb=overflow\n"


def test_overflow_is_sticky_in_record_order():
    # running total leaves range even though the final sum would fit
    assert run(f"a {MAX}\na 1\na -1\n\na\n") == "a=overflow\n"


def test_order_matters_no_overflow():
    assert run(f"a -1\na {MAX}\na 1\n\na\n") == f"a={MAX}\n"


def test_overflow_does_not_affect_other_keys():
    assert run(f"a {MAX}\na 1\nb 2\n\na\nb\n") == "a=overflow\nb=2\n"


def test_zero_total_and_negative():
    assert run("a 5\na -5\nb -7\n\na\nb\n") == "a=0\nb=-7\n"


def test_repeated_queries():
    assert run("a 1\n\na\na\n") == "a=1\na=1\n"


def test_key_looking_like_punctuation():
    assert run("= 1\na=b 2\n\n=\na=b\n") == "==1\na=b=2\n"


def test_cli_exit_code(tmp_path):
    p = tmp_path / "in.txt"
    p.write_bytes("ключ 3\nключ -1\n\nключ\nnope\n".encode())
    r = subprocess.run([sys.executable, str(MAIN), str(p)], capture_output=True)
    assert r.returncode == 0
    assert r.stdout == "ключ=2\nnope=absent\n".encode()
EOF
